/bin/bash -lc "cat > dist/presentation.css <<'EOF'
.sheet {
  width: min(42rem, calc(100% - 2 * var(--gap)));
  margin: clamp(1rem, 5vw, 3rem) auto;
  padding: clamp(1rem, 4vw, 2rem);
  border-radius: var(--radius);
  background: var(--paper);
  line-height: 1.5;
}

.sheet h1 {
  margin: 0 0 0.5rem;
  font-size: clamp(1.5rem, 4vw, 1.875rem);
  line-height: 1.2;
}

.sheet h1 + p {
  margin: 0 0 1.5rem;
  color: var(--subtle);
}

.sheet label {
  display: block;
  margin: var(--gap) 0 0.375rem;
  font-weight: 600;
}

.sheet input,
.sheet select {
  display: block;
  width: 100%;
  min-height: 44px;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet input[aria-invalid=\"true\"] {
  border-color: var(--danger);
}

.sheet [role=\"alert\"] {
  margin: var(--gap) 0 0;
  padding-inline-start: 0.75rem;
  border-inline-start: 3px solid var(--danger);
  color: var(--danger);
  font-weight: 600;
}

.actions {
  display: grid;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.sheet button {
  min-height: 44px;
  padding: 0.625rem 1rem;
  border: 1px solid var(--accent);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--accent);
  font-weight: 600;
  line-height: 1.35;
}

.sheet button[data-primary],
.sheet button#confirm {
  background: var(--accent);
  color: var(--paper);
}

.sheet :is(input, select, button):focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.sheet [role=\"status\"] {
  margin: 1.5rem 0 0;
  padding-top: var(--gap);
  border-top: 1px solid var(--line);
  color: var(--subtle);
  overflow-wrap: anywhere;
}

.sheet dialog {
  width: min(30rem, calc(100% - 2 * var(--gap)));
  max-width: none;
  padding: clamp(1rem, 4vw, 1.5rem);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet dialog h2 {
  margin: 0;
  font-size: 1.25rem;
  line-height: 1.25;
}

@media (min-width: 36rem) {
  .actions {
    grid-template-columns: minmax(0, 1fr) auto;
  }
}
EOF"

/bin/bash -lc "node --input-type=commonjs <<'EOF'
const fs = require('node:fs');
for (const file of fs.readdirSync('visits').filter(x=>x.endsWith('.json'))) {
 const {timeline}=JSON.parse(fs.readFileSync('visits/'+file));
 console.log(file);
 for (const {action,state:s} of timeline.slice(1)) {
  const btns=s.geometry.elements.filter(e=>e.tag==='BUTTON').map(e=>[e.w,e.h,e.scroll,e.client,e.outline]);
  console.log(action.op, action.key||'', s.geometry.page, s.focus, s.dialog.length, s.status,btns);
 }
}
EOF"

/bin/bash -lc "node --input-type=commonjs <<'EOF'
const {readFileSync}=require('node:fs');
const assert=require('node:assert/strict');
function read(id){const r=JSON.parse(readFileSync('visits/'+id+'.json'));assert.equal(r.error,null);return r.timeline.slice(1).map(x=>x.state);}
const mobile=read('2ebb139d-dddf-44c4-98f3-530a047cac5c');
const desktop=read('c2bf192b-eb09-4039-8cf5-fd04eadf55f7');
for(const s of [...mobile,...desktop]){
 assert.equal(s.geometry.page,s.width);
 for (const e of s.geometry.elements){
  assert(e.scroll<=e.client+1 && e.x>=0 && e.x+e.w<=s.width,JSON.stringify(e));
 }
}
assert.equal(mobile[2].fields[0].invalid,'true');
assert.equal(mobile[2].focus.id,'email');
assert.match(mobile[2].status[1]??mobile[2].status[0],/Enter a complete email address/);
assert.equal(mobile.at(-1).geometry.elements.find(e=>e.text.startsWith('Review departmental')).outline,'solid 3px');
assert.equal(desktop[2].dialog.length,1);
assert.equal(desktop[3].dialog.length,0);
assert.match(desktop[5].focus.text,/Review departmental/);
assert.equal(desktop[7].status[0],'duty@example.test / Daily');
assert.equal(desktop[8].fields[0].value,'ops@example.test');
console.log('Layout, validation, keyboard focus, modal and restore checks passed.');
EOF
sha256sum dist/index.html dist/form.js dist/tokens.css"

